// Render text into a frame (2D pixel array)
function renderTextToFrame(frame, text, startX, startY, font, color, displayW, displayH, scale = 1) {
  let curX = startX;
  for (const char of text) {
    const code = char.charCodeAt(0);
    if (code < 32 || code > 126) { curX += (font.width + 1) * scale; continue; }
    const idx = (code - 32) * font.bytesPerChar;
    for (let col = 0; col < font.width; col++) {
      const colByte = font.data[idx + col];
      for (let row = 0; row < font.height; row++) {
        if ((colByte >> row) & 1) {
          for (let sx = 0; sx < scale; sx++) {
            for (let sy = 0; sy < scale; sy++) {
              const px = Math.round(curX + (col * scale) + sx);
              const py = Math.round(startY + (row * scale) + sy);
              if (px >= 0 && px < displayW && py >= 0 && py < displayH) {
                frame[py][px] = color;
              }
            }
          }
        }
      }
    }
    curX += (font.width + 1) * scale;
  }
}

// Measure text width in pixels
function measureText(text, font, scale = 1) {
  if (text.length === 0) return 0;
  return (text.length * (font.width + 1) * scale) - scale;
}

function fontPixel(font, charIdx, col, row) {
  const b = font.data[charIdx * font.bytesPerChar + col];
  return (b >> row) & 1;
}

function downsampleFont(src, newW, newH) {
  const data = [];
  for (let ci = 0; ci < 95; ci++) {
    for (let col = 0; col < newW; col++) {
      let byte = 0;
      for (let row = 0; row < newH; row++) {
        const sx = Math.min(src.width - 1, Math.floor((col * src.width) / newW + src.width / (2 * newW)));
        const sy = Math.min(src.height - 1, Math.floor((row * src.height) / newH + src.height / (2 * newH)));
        if (fontPixel(src, ci, sx, sy)) byte |= 1 << row;
      }
      data.push(byte);
    }
  }
  return { width: newW, height: newH, bytesPerChar: newW, data };
}

function boldFont(src) {
  const data = [];
  const { width: w, height: h, bytesPerChar: bpc } = src;
  const mask = (1 << h) - 1;
  for (let ci = 0; ci < 95; ci++) {
    const idx = ci * bpc;
    for (let col = 0; col < w; col++) {
      let byte = src.data[idx + col];
      const left = col > 0 ? src.data[idx + col - 1] : 0;
      const right = col < w - 1 ? src.data[idx + col + 1] : 0;
      byte = (byte | left | right | (byte >> 1) | (byte << 1)) & mask;
      data.push(byte);
    }
  }
  return { width: w, height: h, bytesPerChar: w, data };
}

