function populateFontSelect(selectEl, currentId, onChange) {
  if (!selectEl) return;
  selectEl.innerHTML = '';
  for (const { id, label } of window.FONT_LIST) {
    const opt = document.createElement('option');
    opt.value = id;
    opt.textContent = label;
    selectEl.appendChild(opt);
  }
  selectEl.value = currentId;
  if (!window.FONTS[selectEl.value]) selectEl.value = '5x7';
  selectEl.onchange = () => onChange(selectEl.value);
}

window.renderTextToFrame = renderTextToFrame;
window.measureText = measureText;
window.populateFontSelect = populateFontSelect;
